      'pipeline:\n  processors:\n    - mapping: |\n        root = this\n        meta processing_start = now()\n        let key = env("CARD_ENCRYPTION_KEY_HEX").decode("hex")\n        let key = if $key.length() != 32 { throw("Expected a 32-byte AES key") } else { $key }\n\n        # AES-GCM requires a unique nonce for each field encryption. Store the\n        # nonce next to the ciphertext so an authorized consumer can decrypt it.\n        let card_number_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.payment.card_number_encrypted = if this.payment.card_number != null {\n          this.payment.card_number.encrypt_aes(\n            "gcm",\n            $key,\n            $card_number_nonce.decode("hex")\n          ).encode("base64")\n        }\n        root.payment.card_number_nonce = if this.payment.card_number != null {\n          $card_number_nonce\n        } else {\n          deleted()\n        }\n\n        # Keep last 4 digits only if the reviewed output contract needs them.\n        root.payment.card_last_four = if this.payment.card_number != null {\n          this.payment.card_number.re_replace_all("[^0-9]", "").slice(-4)\n        }\n\n        # Detect the card brand without retaining the account number.\n        root.payment.card_bin = if this.payment.card_number != null {\n          this.payment.card_number.re_replace_all("[^0-9]", "").slice(0, 6)\n        }\n        root.payment.card_brand = if this.payment.card_number != null {\n          match {\n            this.payment.card_number.re_match("^4") => "visa"\n            this.payment.card_number.re_match("^5[1-5]") => "mastercard"\n            this.payment.card_number.re_match("^3[47]") => "amex"\n            this.payment.card_number.re_match("^6(?:011|5)") => "discover"\n            _ => "unknown"\n          }\n        }\n\n        let cardholder_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.payment.cardholder_name_encrypted = if this.payment.cardholder_name != null {\n          this.payment.cardholder_name.encrypt_aes(\n            "gcm",\n            $key,\n            $cardholder_nonce.decode("hex")\n          ).encode("base64")\n        }\n        root.payment.cardholder_name_nonce = if this.payment.cardholder_name != null {\n          $cardholder_nonce\n        } else {\n          deleted()\n        }\n\n        # CVV is deleted rather than retained in any form.\n        root.payment = root.payment.without(\n          "card_number",\n          "cvv",\n          "cardholder_name"\n        )\n',
