      'pipeline:\n  processors:\n    - mapping: |\n        let key = env("TEMPORAL_ENCRYPTION_KEY_HEX").decode("hex")\n        let key = if $key.length() != 32 { throw("Expected a 32-byte AES key") } else { $key }\n        root = this\n\n        # Parse birth date for analytics extraction\n        let birth_date = if this.customer.date_of_birth != null {\n          this.customer.date_of_birth.ts_parse("2006-01-02")\n        } else { null }\n\n        # Extract temporal analytics before encryption\n        root.customer.birth_year = if $birth_date != null {\n          $birth_date.ts_format("2006").number()\n        }\n        root.customer.current_age = if root.customer.birth_year != null {\n          now().ts_format("2006").number() - root.customer.birth_year\n        }\n\n        # Generate age range for demographic analytics\n        root.customer.age_range = if root.customer.current_age != null {\n          match {\n            root.customer.current_age < 18 => "under_18"\n            root.customer.current_age < 35 => "18_to_34"\n            root.customer.current_age < 55 => "35_to_54"\n            root.customer.current_age < 65 => "55_to_64"\n            _ => "65_plus"\n          }\n        } else { deleted() }\n\n        # Generate generational cohort\n        root.customer.birth_decade = if root.customer.birth_year != null {\n          match {\n            root.customer.birth_year >= 1980 && root.customer.birth_year < 1990 => "1980s"\n            root.customer.birth_year >= 1990 && root.customer.birth_year < 2000 => "1990s"\n            root.customer.birth_year >= 2000 => "2000s"\n            _ => "pre_1980"\n          }\n        }\n\n        # Extract birth season\n        let month = if $birth_date != null { $birth_date.ts_format("01").number() } else { null }\n        root.customer.birth_season = if $month != null {\n          match {\n            $month >= 3 && $month <= 5 => "spring"\n            $month >= 6 && $month <= 8 => "summer"\n            $month >= 9 && $month <= 11 => "autumn"\n            _ => "winter"\n          }\n        }\n\n        # Encrypt exact birth date (HIPAA requirement)\n        let customer_date_of_birth_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.date_of_birth_encrypted = if this.customer.date_of_birth != null {\n          this.customer.date_of_birth.encrypt_aes("gcm", $key, $customer_date_of_birth_nonce.decode("hex")).encode("base64")\n        }\n        root.customer.date_of_birth_nonce = if this.customer.date_of_birth != null { $customer_date_of_birth_nonce } else { deleted() }\n\n        # Remove plaintext birth date\n        root.customer.date_of_birth = deleted()\n    - catch:\n        - mapping: root = deleted()\n',
